import{_ as e,o as i,c as r,a as t}from"./app.CYXXef1p.js";const u=JSON.parse('{"title":"Civilizational Multi-Swarm Hierarchy (WP-1006, WP-5004)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/MULTI_SWARM_HIERARCHY_DEPTH.md","filePath":"reference/MULTI_SWARM_HIERARCHY_DEPTH.md","lastUpdated":1771753292000}'),o={name:"reference/MULTI_SWARM_HIERARCHY_DEPTH.md"};function l(n,a,s,c,d,h){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="civilizational-multi-swarm-hierarchy-wp-1006-wp-5004" tabindex="-1">Civilizational Multi-Swarm Hierarchy (WP-1006, WP-5004) <a class="header-anchor" href="#civilizational-multi-swarm-hierarchy-wp-1006-wp-5004" aria-label="Permalink to &quot;Civilizational Multi-Swarm Hierarchy (WP-1006, WP-5004)&quot;">​</a></h1><p>This document defines the architectural patterns for orchestrating <strong>Swarms of Swarms</strong> at &quot;civilizational&quot; scales (thousands of agents, long-running runs).</p><h2 id="_1-hierarchical-coordination" tabindex="-1">1. Hierarchical Coordination <a class="header-anchor" href="#_1-hierarchical-coordination" aria-label="Permalink to &quot;1. Hierarchical Coordination&quot;">​</a></h2><p>To manage complexity, <code>thegent</code> uses a <strong>Hierarchical Blackboard</strong> system:</p><h3 id="_1-1-the-global-blackboard" tabindex="-1">1.1 The Global Blackboard <a class="header-anchor" href="#_1-1-the-global-blackboard" aria-label="Permalink to &quot;1.1 The Global Blackboard&quot;">​</a></h3><ul><li>Stores high-level goals and &quot;Global Constants.&quot;</li><li>Orchestrated by a <strong>Commander Swarm</strong> (High-level planners).</li></ul><h3 id="_1-2-regional-blackboards-swarms" tabindex="-1">1.2 Regional Blackboards (Swarms) <a class="header-anchor" href="#_1-2-regional-blackboards-swarms" aria-label="Permalink to &quot;1.2 Regional Blackboards (Swarms)&quot;">​</a></h3><ul><li>Each functional swarm (e.g., <code>frontend-swarm</code>, <code>security-swarm</code>, <code>ops-swarm</code>) has its own regional blackboard.</li><li>Agents within the swarm coordinate locally using <strong>Stigmergy</strong> (modifying their regional <code>WORK_STREAM.md</code>).</li></ul><h2 id="_2-multi-swarm-communication-stigmergic-handoff" tabindex="-1">2. Multi-Swarm Communication (Stigmergic Handoff) <a class="header-anchor" href="#_2-multi-swarm-communication-stigmergic-handoff" aria-label="Permalink to &quot;2. Multi-Swarm Communication (Stigmergic Handoff)&quot;">​</a></h2><p>Swarms communicate via &quot;Handoff Artifacts&quot;:</p><ol><li><strong>Frontend Swarm</strong> completes a UI feature and posts a <code>Conformance_Artifact</code> to the Global Blackboard.</li><li><strong>Security Swarm</strong> (monitoring the Global Blackboard) detects the new artifact and triggers a &quot;Pen-Test Cycle&quot; for that feature.</li><li>This indirect coordination allows swarms to scale independently without monolithic bottlenecks.</li></ol><h2 id="_3-scaling-mechanics-wp-5004" tabindex="-1">3. Scaling Mechanics (WP-5004) <a class="header-anchor" href="#_3-scaling-mechanics-wp-5004" aria-label="Permalink to &quot;3. Scaling Mechanics (WP-5004)&quot;">​</a></h2><h3 id="_3-1-distributed-state-partitioning" tabindex="-1">3.1 Distributed State Partitioning <a class="header-anchor" href="#_3-1-distributed-state-partitioning" aria-label="Permalink to &quot;3.1 Distributed State Partitioning&quot;">​</a></h3><ul><li>Redis databases are partitioned by <strong>Swarm_ID</strong> to avoid contention.</li><li>The <strong>Global Shared Log</strong> provides the unified audit trail across all swarms.</li></ul><h3 id="_3-2-hysteresis-per-swarm" tabindex="-1">3.2 Hysteresis per Swarm <a class="header-anchor" href="#_3-2-hysteresis-per-swarm" aria-label="Permalink to &quot;3.2 Hysteresis per Swarm&quot;">​</a></h3><ul><li>Each swarm has its own <strong>Adaptive Concurrency Controller</strong>.</li><li>A <code>frontend-swarm</code> might scale up to 100 agents during a UI sprint, while the <code>compliance-swarm</code> remains at a floor of 2 agents.</li></ul><h2 id="_4-federated-governance" tabindex="-1">4. Federated Governance <a class="header-anchor" href="#_4-federated-governance" aria-label="Permalink to &quot;4. Federated Governance&quot;">​</a></h2><p>Governance policies (Phase 3) are also hierarchical:</p><ul><li><strong>Global Policies</strong>: Mandatory for all swarms (e.g., &quot;Zero PII,&quot; &quot;Cost &lt; $10k&quot;).</li><li><strong>Local Policies</strong>: Specific to a swarm (e.g., &quot;Lint = strict,&quot; &quot;Coverage &gt; 90%&quot;).</li></ul><h2 id="_5-implementation-roadmap-for-hierarchy" tabindex="-1">5. Implementation Roadmap for Hierarchy <a class="header-anchor" href="#_5-implementation-roadmap-for-hierarchy" aria-label="Permalink to &quot;5. Implementation Roadmap for Hierarchy&quot;">​</a></h2><ul><li><strong>WP-5004</strong>: Multi-Redis partitioning support.</li><li><strong>WP-5007</strong>: Hierarchical blackboard implementation.</li><li><strong>WP-6008</strong>: Multi-swarm simulation and load testing.</li></ul><hr><p><em>Cross-ref: <a href="./SWARM_MEMORY_COORDINATION_DEPTH.html">SWARM_MEMORY_COORDINATION_DEPTH.md</a> | <a href="./PHASE_5_SCALE_ROBUSTNESS_DEPTH.html">PHASE_5_SCALE_ROBUSTNESS_DEPTH.md</a></em></p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p><strong>Extended on:</strong> 2026-02-17 <strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>',35)])])}const g=e(o,[["render",l]]);export{u as __pageData,g as default};
